-- Staging das questões da apostila 'Questões de informática.pdf' que NÃO estão no banco (218 itens), texto reextraído e limpo.
-- Origem (banca/ano) não identificada e gabarito da apostila NÃO conferido com prova oficial: ficam numa tabela à parte, visível só para admin. Idempotente.
create table if not exists public.apostila_questoes_pendentes (apostila text not null, numero integer not null, tipo text not null, texto_de_apoio text, enunciado text not null, alternativas jsonb not null default '[]'::jsonb, gabarito_apostila text not null, status text not null default 'origem_a_identificar', note text, created_at timestamptz not null default now(), primary key (apostila, numero));
alter table public.apostila_questoes_pendentes add column if not exists texto_de_apoio text;
alter table public.apostila_questoes_pendentes enable row level security;
drop policy if exists "Admins manage apostila questions" on public.apostila_questoes_pendentes;
create policy "Admins manage apostila questions" on public.apostila_questoes_pendentes for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
on conflict (apostila,numero) do update set tipo=excluded.tipo, texto_de_apoio=excluded.texto_de_apoio, enunciado=excluded.enunciado, alternativas=excluded.alternativas, gabarito_apostila=excluded.gabarito_apostila;
